- `CatchUpOutcome.draw`, if $s_{\text{me}} + x = s_{\text{opp}}$ (the remaining case).

declarations.source:
/-- The direct revelation mechanism induced by a mechanism M and a strategy profile s. -/
def induced_direct_mechanism
    {Player : Type*} {Message : Player → Type*} {Theta : Player → Type*} {Outcome : Type*}
    (M : DirectMechanism Player Message Outcome)
    (s : (i : Player) → Theta i → Message i) :
    DirectMechanism Player Theta Outcome := {
  allocation := fun θ => M.allocation (fun j => s j (θ j))
  payment := fun i θ => M.payment i (fun j => s j (θ j))
}

declarations.reading:
Given types `Player` and `Outcome`, type families `Message` and `Theta` indexed by `Player`, a direct mechanism `M : DirectMechanism Player Message Outcome`, and a strategy profile `s : (i : Player) → Theta i → Message i`, `induced_direct_mechanism` defines a `DirectMechanism Player Theta Outcome` whose:
- allocation function maps each type profile `θ : ∀ i, Theta i` to `M.allocation (fun j => s j (θ j))`;
- payment function maps each player `i : Player` and type profile `θ : ∀ i, Theta i` to `M.payment i (fun j => s j (θ j))`.

A structure `ExchangeEconomy` parameterized by types `Agent` and `Good`, containing:
1. `endowment`: a function `Agent → Good → ℝ` specifying the quantity of each good held by each agent;
2. `utility`: a function `Agent → (Good → ℝ) → ℝ` assigning to each agent a real-valued utility function defined on consumption bundles (functions from `Good` to `ℝ`);
3. `endowment_nonneg`: the condition that for every agent `i : Agent` and every good `g : Good`, `0 ≤ endowment i g`.

declarations.source:
/-- `n` is a crystal with components `a`, `b` (arXiv:1601.03081): `n = ab` is odd, `a, b > 1`, and the biharmonic mean `((a+b)² + (ab+1)²) / (2(a+1)(b+1))` is an integer. -/
def is_crystal_with_components (n a b : ℕ) : Prop :=
  Odd n ∧ 1 < a ∧ 1 < b ∧ n = a * b ∧ 2 * (a + 1) * (b + 1) ∣ (a + b) ^ 2 + (a * b + 1) ^ 2

/-- A weakly consecutive sequence (arXiv:2401.09497, Def. 1.1): if `m ∣ σ(i)` and `m ∣ i - j` then `m ∣ σ(j)`. Positions and values are shifted down by one: `σ : Equiv.Perm (Fin k)` stands for the permutation `i + 1 ↦ σ i + 1` of `{1, …, k}`. -/
def is_weakly_consecutive {k : ℕ} (σ : Equiv.Perm (Fin k)) : Prop :=
  ∀ (m : ℕ) (i j : Fin k), m ∣ (σ i : ℕ) + 1 → (m : ℤ) ∣ (i : ℤ) - (j : ℤ) → m ∣ (σ j : ℕ) + 1

/-- The bundle of agent `i` under the allocation `σ` that gives item `x` to agent `σ x`. -/
def bundle_of {m n : ℕ} (σ : Fin m → Fin n) (i : Fin n) : Finset (Fin m) :=
  Finset.univ.filter fun x => σ x = i

/-- The additive valuation with item values `u`. -/
def additive_valuation {m : ℕ} (u : Fin m → ℝ) : Finset (Fin m) → ℝ :=
  fun S => ∑ j ∈ S, u j

/-- A set function is submodular: marginal values shrink as the set grows. -/
def is_submodular {m : ℕ} (v : Finset (Fin m) → ℝ) : Prop :=
  ∀ S T j, S ⊆ T → j ∉ T → v (insert j T) - v T ≤ v (insert j S) - v S

/-- Every marginal value is 0 or 1. -/
def has_binary_marginals {m : ℕ} (v : Finset (Fin m) → ℝ) : Prop :=
  ∀ S j, j ∉ S → v (insert j S) = v S ∨ v (insert j S) = v S + 1

/-- A simple game on `n` players (arXiv:2607.07013, Sec. 10): a monotone `v : 2^[n] → {0,1}` with `v(∅) = 0` and `v([n]) = 1`; coalitions with `v S = true` are winning. -/
def is_simple_game {n : ℕ} (v : Finset (Fin n) → Bool) : Prop :=
  (∀ S T, S ⊆ T → v S = true → v T = true) ∧ v ∅ = false ∧ v Finset.univ = true

/-- A game is weighted (Taylor-Zwicker): there are nonnegative weights `w` and a quota `q` such that a coalition wins exactly when its total weight reaches the quota. -/
def is_weighted_game {n : ℕ} (v : Finset (Fin n) → Bool) : Prop :=
  ∃ (w : Fin n → ℝ) (q : ℝ), (∀ i, 0 ≤ w i) ∧ ∀ S, v S = true ↔ q ≤ ∑ i ∈ S, w i

/-- Minimum EFX share (arXiv:2502.02815, Def. 10 with F = EFX, equal entitlements): agent `i`'s bundle under `σ` is worth to her at least her bundle in some allocation `τ` that is EFX-fair to her. -/
def is_mxs_fair {m n : ℕ} (v : Fin n → Finset (Fin m) → ℝ) (σ : Fin m → Fin n) (i : Fin n) : Prop :=
  ∃ τ : Fin m → Fin n, is_efx_fair v τ i ∧ v i (bundle_of τ i) ≤ v i (bundle_of σ i)

/-- Woman's view of two outcomes under her true ranking `T` (0 = best, unmatched worst): `a` is at least as good as `b`. -/
def woman_weakly_prefers {nm : ℕ} (T : Fin nm → Fin nm) (a b : Option (Fin nm)) : Prop :=
  ∀ y ∈ b, ∃ x ∈ a, T x ≤ T y

/-- Woman's view of two outcomes under her true ranking `T` (0 = best, unmatched worst): `a` is strictly better than `b`. -/
def woman_strictly_prefers {nm : ℕ} (T : Fin nm → Fin nm) (a b : Option (Fin nm)) : Prop :=
  ∃ x ∈ a, ∀ y ∈ b, T x < T y

/-- The allocation `σ` is an orientation of the multigraph whose edge `e` joins `(ends e).1` and `(ends e).2`: every edge goes to one of its two endpoints. -/
def is_orientation {m n : ℕ} (ends : Fin m → Fin n × Fin n) (σ : Fin m → Fin n) : Prop :=
  ∀ e, σ e = (ends e).1 ∨ σ e = (ends e).2

/-- A monotone valuation into the nonnegative reals: `0 ≤ v ∅` and `S ⊆ T → v S ≤ v T`. -/
def is_monotone_valuation {m : ℕ} (v : Finset (Fin m) → ℝ) : Prop :=
  0 ≤ v ∅ ∧ ∀ S T, S ⊆ T → v S ≤ v T

/-- The subsidy normalisation: the largest marginal value of any item is exactly 1. -/
def has_max_marginal_one {m : ℕ} (v : Finset (Fin m) → ℝ) : Prop :=
  (∀ S e, v (insert e S) - v S ≤ 1) ∧ ∃ S e, v (insert e S) - v S = 1

/-- A set of items on a path `0, 1, …, m - 1` is connected: it contains every item lying between two of its items. -/
def is_path_connected {m : ℕ} (B : Finset (Fin m)) : Prop :=
  ∀ x ∈ B, ∀ y ∈ B, ∀ z, x ≤ z → z ≤ y → z ∈ B

/-- Epistemic EF1 (arXiv:2502.02815, Def. 9 with F = EF1): some allocation `τ` gives agent `i` the same bundle as `σ` and is EF1-fair to her. -/
def is_eef1_fair {m n : ℕ} (v : Fin n → Finset (Fin m) → ℝ) (σ : Fin m → Fin n) (i : Fin n) : Prop :=
  ∃ τ : Fin m → Fin n, bundle_of τ i = bundle_of σ i ∧ is_ef1_fair v τ i

/-- Every agent's bundle under `σ` is connected on the path. -/
def is_connected_allocation {m n : ℕ} (σ : Fin m → Fin n) : Prop :=
  ∀ i, is_path_connected (bundle_of σ i)

/-- Pareto optimality for chores (arXiv:2608.16130, Def. 2.4): no (integral) allocation Pareto-dominates `σ`. -/
def is_pareto_optimal_chores {m n : ℕ} (c : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : Prop :=
  ¬ ∃ τ, pareto_dominates_chores c τ σ

/-- The relevant items `E_i` of agent `i` in the multigraph orientation model: the edges incident to vertex `i`. -/
def incident_edges {m n : ℕ} (ends : Fin m → Fin n × Fin n) (i : Fin n) : Finset (Fin m) :=
  Finset.univ.filter fun e => (ends e).1 = i ∨ (ends e).2 = i

/-- The parallel class of edges joining agents `i` and `j` (the items in `E_i ∩ E_j`). -/
def edges_between {m n : ℕ} (ends : Fin m → Fin n × Fin n) (i j : Fin n) : Finset (Fin m) :=
  Finset.univ.filter fun e => ends e = (i, j) ∨ ends e = (j, i)

/-- The orientation `i → i + 1, i → i + 2 (mod n)` of the complete graph on `Fin n`. -/
def cyclic_two_orientation (n : ℕ) (i j : Fin n) : Bool :=
  decide ((j.val + n - i.val) % n = 1 ∨ (j.val + n - i.val) % n = 2)

/-- A chores instance in the model of arXiv:2410.15738 (Sec. 2): every cost is nonnegative and every agent's costs are normalised, `c i (O) = 1`. -/
def is_normalized_chores_instance {m n : ℕ} (c : Fin n → Fin m → ℝ) : Prop :=
  (∀ i j, 0 ≤ c i j) ∧ ∀ i, ∑ j, c i j = 1

/-- Social cost of an allocation (arXiv:2410.15738, Sec. 2): `SC(A) = ∑ i, c i (A i)`. -/
def social_cost {m n : ℕ} (c : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : ℝ :=
  ∑ i, additive_valuation (c i) (bundle_of σ i)

/-- Two-bundle EF1 condition: the owner of `A`, with costs `w`, is EF1 towards `B`. -/
def ef1cost_pair_ok {m : ℕ} (w : Fin m → ℝ) (A B : Finset (Fin m)) : Prop :=
  ∑ j ∈ A, w j ≤ ∑ j ∈ B, w j ∨ ∃ e ∈ A, ∑ j ∈ A, w j - w e ≤ ∑ j ∈ B, w j

/-- Utility vector of the allocation `σ` (good `x` goes to agent `σ x`) under additive values `u`. -/
def goods_utility {m n : ℕ} (u : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : Fin n → ℝ :=
  fun i => additive_valuation (u i) (bundle_of σ i)

/-- `y` is strictly leximin-better than `x`: the sorted profile of `x` is lexicographically smaller. -/
def leximin_lt {n : ℕ} (x y : Fin n → ℝ) : Prop :=
  List.Lex (· < ·) (leximin_profile x) (leximin_profile y)

/-- Monroe score of an assignment: the number of voters assigned to a candidate they approve. -/
def monroe_score {n m : ℕ} (A : Fin n → Finset (Fin m)) (π : Fin n → Fin m) : ℕ :=
  (Finset.univ.filter fun i => π i ∈ A i).card

/-- `σ` is a leximin-optimal allocation among the EF1 allocations: it is EF1 and no EF1 allocation is strictly leximin-better. -/
def is_leximin_ef1 {m n : ℕ} (u : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : Prop :=
  is_ef1_goods u σ ∧ ∀ τ, is_ef1_goods u τ → ¬ leximin_lt (goods_utility u σ) (goods_utility u τ)

/-- Pareto domination for goods: under `τ` every agent is at least as well off as under `σ`, and some agent strictly better off. -/
def pareto_dominates_goods {m n : ℕ} (u : Fin n → Fin m → ℝ) (τ σ : Fin m → Fin n) : Prop :=
  (∀ i, goods_utility u σ i ≤ goods_utility u τ i) ∧ ∃ i, goods_utility u σ i < goods_utility u τ i

/-- An allocation of goods is Pareto optimal if no allocation Pareto-dominates it. -/
def is_pareto_optimal_goods {m n : ℕ} (u : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : Prop :=
  ¬ ∃ τ, pareto_dominates_goods u τ σ

/-- The instance: four agents, six goods, integer values each summing to 20. -/
def lxv_values : Fin 4 → Fin 6 → ℕ :=
  ![![6, 2, 3, 6, 1, 2], ![1, 1, 0, 5, 5, 8], ![4, 0, 0, 2, 1, 13], ![1, 1, 0, 2, 2, 14]]

/-- Integer leximin profile for the instance `lxv_values`. -/
def lxv_profile (a : Fin 6 → Fin 4) : List ℕ :=
  (List.ofFn fun i => lxv_val a i i).insertionSort (· ≤ ·)

/-- `w` lies in the standard simplex: nonnegative entries summing to 1. -/
def in_std_simplex {n : ℕ} (w : Fin n → ℝ) : Prop :=
  (∀ i, 0 ≤ w i) ∧ ∑ i, w i = 1

/-- `w` is an optimal weight vector of the inverse power problem `(m, q, β^p)`: it lies in the simplex and minimises the discrepancy over the simplex. -/
def is_optimal_banzhaf_weights {n : ℕ} (m : Fin n → ℝ) (p q : ℝ) (w : Fin n → ℝ) : Prop :=
  in_std_simplex w ∧ ∀ w', in_std_simplex w' → banzhaf_discrepancy m p q w ≤ banzhaf_discrepancy m p q w'

/-- The rational discrepancy for target `(3/10, 7/10, 0)` of the index with pivot counts `bz3_cnt x`. -/
def bz3_discr (x : Fin 8 → Bool) : ℚ :=
  let T : ℚ := (bz3_cnt x 0 + bz3_cnt x 1 + bz3_cnt x 2 : ℕ)
  |3 / 10 - (bz3_cnt x 0 : ℚ) / T| + |7 / 10 - (bz3_cnt x 1 : ℚ) / T| + |0 - (bz3_cnt x 2 : ℚ) / T|

/-- The eight coalitions of three players, indexed by bit pattern (bit `j` set iff player `j` is in). -/
def bz3_coal : Fin 8 → Finset (Fin 3) :=
  ![∅, {0}, {1}, {0, 1}, {2}, {0, 2}, {1, 2}, {0, 1, 2}]

