open Finset in
/-- Coordinates of the slice prior: the `m`-subsets of `Fin (2m+1)`. -/
abbrev persuasion_slice_coord (m : ℕ) := {i : Finset (Fin (2 * m + 1)) // i.card = m}

/-- A population paradox (In This Apportionment Lottery, the House Always Wins, Sec. 2) of the apportionment solution `f` between `(p, h)` and `(p', h')`: states `i ≠ j` with `p'_i ≥ p_i` and `p'_j ≤ p_j`, yet `i` loses a seat and `j` gains one. -/
def population_paradox {n : ℕ} (f : (Fin n → ℕ) → ℕ → (Fin n → ℕ)) (p p' : Fin n → ℕ) (h h' : ℕ) : Prop :=
  ∃ i j, i ≠ j ∧ p i ≤ p' i ∧ p' j ≤ p j ∧ f p' h' i < f p h i ∧ f p h j < f p' h' j

/-- The quota-compliant seat vectors for profile `p` at house size 8. -/
def apx_candidates (p : Fin 4 → ℕ) : List (Fin 4 → ℕ) :=
  apx_all_vectors.filter (apx_quota p 8)

/-- Feasibility in the general-approval embedding of a temporal election: a set of (candidate, round) pairs is feasible if it uses each round at most once. -/
def temporal_feasible {ℓ m : ℕ} (X : Finset (Fin m × Fin ℓ)) : Prop :=
  ∀ p ∈ X, ∀ q ∈ X, p.2 = q.2 → p.1 = q.1

/-- Ballots of the counterexample: voter 0 approves candidate 0 in rounds 0–2 only, voter 1 approves candidate 0 in rounds 3–5 only, voters 2 and 3 approve candidate 1 in every round. -/
def tfjr_ballot : Fin 4 → Fin 6 → Finset (Fin 2) := fun i r =>
  if i = 0 then (if r.val < 3 then {0} else ∅)
  else if i = 1 then (if 3 ≤ r.val then {0} else ∅) else {1}

/-- Pure-strategy equilibrium of a Publication Choice Problem (arXiv:2511.13678, Definition 1): every type best responds to the venue impacts `v`, and `v` is consistent with the action profile `a`. -/
def pcp_is_equilibrium {n k : ℕ} (α β : ℝ) (θ μ : Fin n → ℝ) (c a : Fin n → Fin k → ℝ) (v : Fin k → ℝ) : Prop :=
  (∀ i, pcp_is_best_response α β (c i) v (a i)) ∧ ∀ j, v j = pcp_venue_impact θ μ a j

/-- Assumption 1 (Monotone Cost Ratio) of arXiv:2511.13678: for types `θ i < θ i'` and venues `j < j'`, `c i j / c i' j < c i j' / c i' j'`. -/
def pcp_monotone_cost_ratio {n k : ℕ} (θ : Fin n → ℝ) (c : Fin n → Fin k → ℝ) : Prop :=
  ∀ (i i' : Fin n) (j j' : Fin k), θ i < θ i' → j < j' → c i j / c i' j < c i j' / c i' j'

/-- Assumption 2 (Non-competitive venue) of arXiv:2511.13678: the least competitive venue (index 0) costs the same for every type. -/
def pcp_noncompetitive_venue {n k : ℕ} (c : Fin n → Fin k → ℝ) : Prop :=
  ∀ (i i' : Fin n) (j : Fin k), j.val = 0 → c i j = c i' j

