/-- Two-point instances: every player's reward is `x i 0` with probability `w i 0` and `x i 1` otherwise, with `0 ≤ x i 1 ≤ x i 0`. -/
def spi_is_two_point_instance {N : ℕ} (x w : Fin N → Fin 2 → ℝ) : Prop :=
  ∀ i, 0 ≤ x i 1 ∧ x i 1 ≤ x i 0 ∧ 0 ≤ w i 0 ∧ w i 0 ≤ 1 ∧ w i 1 = 1 - w i 0

/-- Evaluation of a list of 3x3 triads on input matrices A and B. -/
def eval_matrix3_decomposition {R : Type*} [CommSemiring R] (L : List (Matrix3Triad R)) (A B : Matrix (Fin 3) (Fin 3) R) : Matrix (Fin 3) (Fin 3) R :=
  (L.map (fun t => eval_matrix3_triad t A B)).sum

/-- A triad decomposition is valid for 3x3 matrix multiplication if it computes A * B for all A and B. -/
def is_valid_matrix3_decomposition {R : Type*} [CommSemiring R] (L : List (Matrix3Triad R)) : Prop :=
  ∀ A B : Matrix (Fin 3) (Fin 3) R, eval_matrix3_decomposition L A B = A * B

/-- The tensor rank of 3x3 matrix multiplication over R is at most r. -/
def matrix3_tensor_rank_le (R : Type*) [CommSemiring R] (r : ℕ) : Prop :=
  ∃ L : List (Matrix3Triad R), L.length ≤ r ∧ is_valid_matrix3_decomposition L

/-- The tensor rank of 3x3 matrix multiplication over R is at least r. -/
def matrix3_tensor_rank_ge (R : Type*) [CommSemiring R] (r : ℕ) : Prop :=
  ∀ L : List (Matrix3Triad R), is_valid_matrix3_decomposition L → r ≤ L.length

/-- The tensor rank of 3x3 matrix multiplication over R is exactly r. -/
def matrix3_tensor_rank_exactly (R : Type*) [CommSemiring R] (r : ℕ) : Prop :=
  matrix3_tensor_rank_le R r ∧ matrix3_tensor_rank_ge R r

/-- The syndrome of the layer of m disjoint CCZ gates on qubits {3j, 3j+1, 3j+2}: 1 on those triples and 0 on every other set. -/
def ccz_layer_syndrome (m : ℕ) (A : Finset (Fin (3 * m))) : ZMod 2 :=
  if ∃ j : Fin m, A = {⟨3 * j.val, by omega⟩, ⟨3 * j.val + 1, by omega⟩, ⟨3 * j.val + 2, by omega⟩}
  then 1 else 0

/-- A resolution refutation of F: a resolution derivation from F ending in the empty clause. -/
def is_resolution_refutation {V : Type*} (F : Finset (Finset (CnfLit V))) (π : List (Finset (CnfLit V))) : Prop :=
  is_resolution_derivation F π ∧ π.getLast? = some ∅

/-- The treewidth of a graph: the least width of a tree decomposition. -/
noncomputable def graph_treewidth {α : Type*} (G : SimpleGraph α) : ℕ :=
  sInf {w | has_tree_decomposition_of_width_le G w}

explanation.summary:
To verify that $[\{x_0\}, \{
eg x_0\}, \emptyset]$ is a resolution refutation of the formula $\{\{x_0\}, \{
eg x_0\}\}$, we check that the derivation ends in the empty clause and that every clause in the sequence is legally derived. The first condition holds immediately by definition because the final entry is $\emptyset$. For the second condition, we inspect each index: the first two clauses $\{x_0\}$ and $\{
eg x_0\}$ are axioms present in the input formula, and the final clause $\emptyset$ is obtained by resolving the first two clauses on the variable $0$.

steps.explanation:
For $i = 1$, the clause is $\{
eg x_0\}$. As with the first clause, we select the axiom alternative (`Or.inl`), verifying that $\{
eg x_0\}$ belongs to the input formula $\{\{x_0\}, \{
eg x_0\}\}$ via finite set membership (`Finset.mem_cons`).

For $i = 2$, the clause is $\emptyset$. We select the resolution rule (`Or.inr (Or.inr ...)`), specifying clause 0 ($\{x_0\}$) and clause 1 ($\{
eg x_0\}$) as the premises. Both indices precede 2, as confirmed by translating the ordering on $\mathrm{Fin}\; 3$ to natural numbers (`Fin.lt_def`). Choosing the pivot variable $0$ and empty residual clauses $C = \emptyset$ and $D = \emptyset$, the derivation condition reduces to the three set equalities $\{x_0\} = \emptyset \cup \{x_0\}$, $\{
eg x_0\} = \emptyset \cup \{
eg x_0\}$, and $\emptyset = \emptyset \cup \emptyset$, all of which are closed by simplification.

