open Finset in
/-- The probability simplex `Δ_k`. -/
def gpa_simplex (k : ℕ) : Set (Fin k → ℝ) :=
  {σ | (∀ i, 0 ≤ σ i) ∧ ∑ i, σ i = 1}

/-- The unit cube `[0,1]^k`. -/
def gpa_cube (k : ℕ) : Set (Fin k → ℝ) :=
  {x | ∀ i, 0 ≤ x i ∧ x i ≤ 1}

/-- The set of values `u*(σ) - h(σ)` over the simplex (left side of Eq. (5.4)). -/
def gpa_lhsSet {k : ℕ} (e : Fin k → Fin k → ℝ) : Set ℝ :=
  (fun σ => gpa_uStar e σ - gpa_cost σ) '' gpa_simplex k

/-- The set of values `u*(x)` over the cube (right side of Eq. (5.4), before dividing by `k`). -/
def gpa_rhsSet {k : ℕ} (e : Fin k → Fin k → ℝ) : Set ℝ :=
  gpa_uStar e '' gpa_cube k

/-- The variables of a CNF formula given as a finite set of clauses, each a finite set of literals. -/
def cnf_vars {V : Type*} [DecidableEq V] (F : Finset (Finset (CnfLit V))) : Finset V :=
  F.biUnion fun C => C.image cnf_lit_var

declarations.reading:
There exists a collection $S$ of 11 subsets of $\mathrm{Fin}(5)$ such that:
1. Every $y \in S$ is nonempty;
2. For every subset $A \subseteq \mathrm{Fin}(5)$ with $1 \le |A| \le 3$, the number of sets in $S$ that contain $A$ is congruent modulo 2 to $1$ if $A = \{i, i+1, i+2\}$ for some $i \in \mathrm{Fin}(3)$, and congruent modulo 2 to $0$ otherwise.

