/-- `π` is a maximum-weight perfect matching. -/
def team_isMaxWeight {n : ℕ} (P : Fin n → Fin n → ℝ) (π : Equiv.Perm (Fin n)) : Prop :=
  ∀ σ : Equiv.Perm (Fin n), team_weight P σ ≤ team_weight P π

/-- `π` is an optimal line-up (maximises the winning probability). -/
def team_isOptimal {n : ℕ} (P : Fin n → Fin n → ℝ) (π : Equiv.Perm (Fin n)) : Prop :=
  ∀ σ : Equiv.Perm (Fin n), team_winProb P σ ≤ team_winProb P π

/-- The comparison oracle: the answer to query `(a, b)` on the poset `P`. -/
def PMPoset.ans {n : ℕ} (P : PMPoset n) (a b : Fin n) : PMAns :=
  if P.lt a b then PMAns.lt else if P.lt b a then PMAns.gt else PMAns.inc

/-- `T` correctly finds the minimal elements of every poset of width at most `2` on `Fin n`. -/
def PMTree.Correct2 {n : ℕ} (T : PMTree n) : Prop :=
  ∀ P : PMPoset n, P.Width2 → T.run P = P.minSet

/-- A list of query/answer facts is satisfied by `P`. -/
def PMSat {n : ℕ} (P : PMPoset n) (F : List (Fin n × Fin n × PMAns)) : Prop :=
  ∀ f ∈ F, P.ans f.1 f.2.1 = f.2.2

/-- The pure profile `σ` is an `ε`-approximate pure Nash equilibrium. -/
def AGGame.PureNE {n s : ℕ} (G : AGGame n s) (ε : ℚ) (σ : Fin n → Fin s) : Prop :=
  ∀ p : Fin n, ∀ j : Fin s, G.u p j (agCnt σ p) ≤ G.u p (σ p) (agCnt σ p) + ε

/-- Integer form of the matching-pennies payoffs. -/
def agMPv (p i : Fin 2) (y : Fin 2 → ℕ) : ℕ :=
  if p = 0 then (if y i = 1 then 1 else 0) else (if y i = 0 then 1 else 0)

/-- A scaling function in the sense of arXiv 2402.18908: continuous and positive on `[0,1]`. -/
def fse_IsScaling (q : ℝ → ℝ) : Prop :=
  ContinuousOn q (Set.Icc 0 1) ∧ ∀ y ∈ Set.Icc (0 : ℝ) 1, 0 < q y

/-- A deterministic mechanism maps every profile in `[0,1]^n` to a facility location in `[0,1]`. -/
def fse_MapsToDomain {n : ℕ} (f : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ x : Fin n → ℝ, fse_InDomain x → f x ∈ Set.Icc (0 : ℝ) 1

/-- Surjectivity (onto `[0,1]`). -/
def fse_Surjective {n : ℕ} (f : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ y ∈ Set.Icc (0 : ℝ) 1, ∃ x : Fin n → ℝ, fse_InDomain x ∧ f x = y

/-- Anonymity: permuting the agents' labels does not change the outcome. -/
def fse_Anonymous {n : ℕ} (f : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ (σ : Equiv.Perm (Fin n)) (x : Fin n → ℝ), f (x ∘ σ) = f x

/-- `f` is a dictatorship: some fixed agent always gets her own location. -/
def fse_Dictatorship {n : ℕ} (f : (Fin n → ℝ) → ℝ) : Prop :=
  ∃ i : Fin n, ∀ x : Fin n → ℝ, fse_InDomain x → f x = x i

/-- A scaling-oblivious mechanism is strategyproof for *every* scaling function: the mechanism does not know `q`, and no agent can gain under any continuous positive `q`. -/
def fse_SPAll {n : ℕ} (f : (Fin n → ℝ) → ℝ) : Prop :=
  ∀ q : ℝ → ℝ, fse_IsScaling q → fse_SP q f

/-- Agent `i`'s total cost of the chores selected by `P`, computed by a fold for the kernel. -/
def pmms3c_cost_nat (i : Fin 3) (P : Fin 9 → Bool) : ℕ :=
  (List.finRange 9).foldr (fun g acc => (if P g then pmms3c_cost i g else 0) + acc) 0

