/-- The Nash welfare of the allocation `σ` under additive valuations `v`: the product of the agents' values for their bundles. -/
def nash_welfare {m n : ℕ} (v : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : ℝ :=
  ∏ i, additive_valuation (v i) (bundle_of σ i)

/-- The utilitarian (social) welfare of the allocation `σ` under additive valuations `v`: the sum of the agents' values for their bundles. -/
def utilitarian_welfare {m n : ℕ} (v : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : ℝ :=
  ∑ i, additive_valuation (v i) (bundle_of σ i)

/-- `σ` maximizes Nash welfare among all allocations of the goods. -/
def is_mnw_allocation {m n : ℕ} (v : Fin n → Fin m → ℝ) (σ : Fin m → Fin n) : Prop :=
  ∀ τ, nash_welfare v τ ≤ nash_welfare v σ

/-- `S` induces a connected subgraph of `G` (connectedness includes nonemptiness). -/
def is_connected_vertex_set {V : Type*} (G : SimpleGraph V) (S : Set V) : Prop :=
  (G.induce S).Connected

/-- Adjacency of the 8-vertex counterexample graph (18 edges), as neighbourhood bitmasks. -/
def poc8_adj (a b : Fin 8) : Bool :=
  ((![240, 232, 216, 198, 165, 147, 143, 127] : Fin 8 → ℕ) a).testBit b

/-- The 8-vertex counterexample graph. -/
def poc8_graph : SimpleGraph (Fin 8) :=
  { Adj := fun a b => poc8_adj a b = true
    symm := ⟨by decide⟩
    loopless := ⟨by decide⟩ }

/-- One BFS step: `R` plus all vertices of `S` adjacent to `R`. -/
def poc8_step (S R : Fin 8 → Bool) : Fin 8 → Bool :=
  fun v => R v || (S v && (List.finRange 8).any fun w => R w && poc8_adj w v)

/-- Total `u`-value of the vertices selected by `P`. -/
def poc8_val (P : Fin 8 → Bool) : ℕ :=
  (List.finRange 8).foldr (fun v acc => (if P v then poc8_u v else 0) + acc) 0

/-- Utility of player `v` in the unweighted Max-k-Cut game on `G` under the coloring `σ`: the number of neighbours of `v` whose color differs from `v`'s. -/
def maxcut_utility {V : Type} [Fintype V] (G : SimpleGraph V) [DecidableRel G.Adj] {k : ℕ} (σ : V → Fin k) (v : V) : ℕ :=
  (Finset.univ.filter fun w => G.Adj v w ∧ σ w ≠ σ v).card

/-- Social welfare of a coloring in the unweighted Max-k-Cut game: the sum of the players' utilities, which is twice the number of bichromatic edges. -/
def maxcut_welfare {V : Type} [Fintype V] (G : SimpleGraph V) [DecidableRel G.Adj] {k : ℕ} (σ : V → Fin k) : ℕ :=
  ∑ v, maxcut_utility G σ v

/-- An optimal coloring of the Max-k-Cut game: it maximizes social welfare (equivalently the cut value) over all colorings `V → Fin k`. -/
def is_maxcut_optimal {V : Type} [Fintype V] (G : SimpleGraph V) [DecidableRel G.Adj] {k : ℕ} (σ : V → Fin k) : Prop :=
  ∀ τ : V → Fin k, maxcut_welfare G τ ≤ maxcut_welfare G σ

/-- A strong equilibrium of the Max-k-Cut game: a coloring admitting no strong deviation. -/
def is_maxcut_strong_equilibrium {V : Type} [Fintype V] (G : SimpleGraph V) [DecidableRel G.Adj] {k : ℕ} (σ : V → Fin k) : Prop :=
  ∀ (S : Finset V) (τ : V → Fin k), ¬ is_maxcut_strong_deviation G σ S τ

