/-- The threshold `μ(n)` of arXiv:2610.06125 for monotone valuations over goods: the largest `m` such that every instance with `n` agents and at most `m` goods has an MMS allocation. As an `sSup` in `ℕ` it is `0` when no largest such `m` exists; this happens only for `n = 1` (for `n ≥ 2` the set is bounded by the paper's Theorem 6, and for `n = 0` it is `{0}`). -/
noncomputable def mms_threshold_monotone (n : ℕ) : ℕ :=
  sSup {m | ∀ m' ≤ m, mms_exists_monotone n m'}

/-- A walk of an agent in the temporal graph `G` (snapshot `G t` at time step `t`): at each step it waits or moves along one edge of the current snapshot. -/
def is_temporal_walk {n : ℕ} (G : ℕ → SimpleGraph (Fin n)) (w : ℕ → Fin n) : Prop :=
  ∀ t, w (t + 1) = w t ∨ (G t).Adj (w t) (w (t + 1))

/-- The walk `w` has visited every vertex by time `T`. -/
def temporal_walk_explores_by {n : ℕ} (w : ℕ → Fin n) (T : ℕ) : Prop :=
  ∀ u, ∃ t ≤ T, w t = u

/-- `H` is a spanning path on `Fin n`: for some ordering `f` of the vertices, two vertices are adjacent exactly when they are consecutive in the ordering. -/
def is_spanning_path_graph {n : ℕ} (H : SimpleGraph (Fin n)) : Prop :=
  ∃ f : Equiv.Perm (Fin n), ∀ a b, H.Adj a b ↔ ((f a : ℕ) + 1 = f b ∨ (f b : ℕ) + 1 = f a)

