open Finset BoolFourier in
/-- Bounds a Fourier coefficient using distance from the corresponding linear function. **Source:** [OD14, §1.6 (Fourier soundness proof)]. -/
lemma BoolBLR.fourier_coeff_le_of_dist_ge
    {n : ℕ}
    (f g : hypercube n → Bool)
    (S : Finset (Fin n))
    (hchar : lift_pm1 g = char_S S)
    (hdist : bool_dist f g ≥ ε) :
    fourier_coeff (lift_pm1 f) S ≤ 1 - 2 * ε := by
  -- Reduce to f̂(S) ≤ 1 - 2 · dist(f,g).
  refine le_trans ?_ ( sub_le_sub_left ( mul_le_mul_of_nonneg_left hdist <| by norm_num ) 1 );
  unfold fourier_coeff bool_dist;
  unfold inner_product expectation;
  -- Pointwise identity: lift(f)(x)·lift(g)(x) = 1 - 2·𝟙[f(x) ≠ g(x)].
  simp_all +decide [ ← hchar, Finset.sum_ite , (fourier_coeff_le_of_dist_ge_aux_h_lift_pm1 f g)];
  ring_nf; norm_num [ card_hypercube ] ;
  norm_num [ ← mul_pow ]

-- if f is epsilon-far from all linear functions, then f-hat (S) ≤ 1 - 2 * ε for all S

/-- `(M₁, M₂)` has a common coloring with `k` colors: a map `c` giving each element of the ground set of `M₁` a color in `{0, …, k - 1}` such that every color class is independent in both matroids. -/
def matroid_common_colorable {α : Type*} (M₁ M₂ : Matroid α) (k : ℕ) : Prop :=
  ∃ c : α → ℕ, (∀ e ∈ M₁.E, c e < k) ∧ ∀ γ : ℕ,
    M₁.Indep {e | e ∈ M₁.E ∧ c e = γ} ∧ M₂.Indep {e | e ∈ M₁.E ∧ c e = γ}

/-- `(M₁, M₂)` is `k`-list-colorable: for every assignment of finite lists of colors (natural numbers) with at least `k` colors to every element of the ground set, there is a choice of a color from each element's list such that every color class is independent in both matroids. -/
def matroid_common_list_colorable {α : Type*} (M₁ M₂ : Matroid α) (k : ℕ) : Prop :=
  ∀ L : α → Finset ℕ, (∀ e ∈ M₁.E, k ≤ (L e).card) →
    ∃ c : α → ℕ, (∀ e ∈ M₁.E, c e ∈ L e) ∧ ∀ γ : ℕ,
      M₁.Indep {e | e ∈ M₁.E ∧ c e = γ} ∧ M₂.Indep {e | e ∈ M₁.E ∧ c e = γ}

/-- The common chromatic number `χ(M₁, M₂)`: the least number of colors in a common coloring (`0` if there is none). -/
noncomputable def matroid_common_chromatic_number {α : Type*} (M₁ M₂ : Matroid α) : ℕ :=
  sInf {k | matroid_common_colorable M₁ M₂ k}

/-- The common list chromatic number `χ_ℓ(M₁, M₂)`: the least `k` such that `(M₁, M₂)` is `k`-list-colorable (`0` if there is none). -/
noncomputable def matroid_common_list_chromatic_number {α : Type*} (M₁ M₂ : Matroid α) : ℕ :=
  sInf {k | matroid_common_list_colorable M₁ M₂ k}

/-- Independent edge sets of `K₄`, edges numbered `0 = 01, 1 = 23, 2 = 02, 3 = 13, 4 = 03, 5 = 12` (so `{0,1}`, `{2,3}`, `{4,5}` are the opposite pairs): forests, i.e. at most three edges and not a triangle. -/
abbrev k4_forest (I : Finset (Fin 6)) : Prop :=
  I.card ≤ 3 ∧ I ≠ {0, 2, 5} ∧ I ≠ {0, 3, 4} ∧ I ≠ {1, 2, 4} ∧ I ≠ {1, 3, 5}

/-- The multilinear extension `F(x) = ∑_S f(S) ∏_{u ∈ S} x_u ∏_{u ∉ S} (1 - x_u)` of a set function `f` on `Fin m`. -/
def multilinear_extension {m : ℕ} (f : Finset (Fin m) → ℝ) (x : Fin m → ℝ) : ℝ :=
  ∑ S : Finset (Fin m), f S * (∏ u ∈ S, x u) * ∏ u ∈ Sᶜ, (1 - x u)

/-- The indicator vector `1_S ∈ ℝ^m` of `S ⊆ Fin m`. -/
def finset_indicator_vec {m : ℕ} (S : Finset (Fin m)) : Fin m → ℝ :=
  fun u => if u ∈ S then 1 else 0

/-- The matroid polytope `P(M) = conv{1_S : S independent in M}` of a matroid on `Fin m`. -/
def matroid_polytope {m : ℕ} (M : Matroid (Fin m)) : Set (Fin m → ℝ) :=
  convexHull ℝ {x | ∃ S : Finset (Fin m), M.Indep ↑S ∧ x = finset_indicator_vec S}

/-- The unit-capacity partition matroid M₂ whose independent sets meet every class of three_k4_partition_class at most once. -/
def three_k4_partition_matroid : Matroid (Fin 3 × Fin 6) :=
  (Matroid.freeOn (Set.univ : Set (Fin 9))).comap three_k4_partition_class

/-- The pure tensor `x ⊗ y ⊗ z` in `ℂⁿ ⊗ ℂⁿ ⊗ ℂⁿ`, with entries `xᵢ yⱼ zₖ`. -/
def tensor3_pure {n : ℕ} (x y z : Fin n → ℂ) : Fin n → Fin n → Fin n → ℂ :=
  fun i j k => x i * y j * z k

/-- Number of signs on a board of the sign-preservation-with-reuse game: a board has `n` cells, each empty (`none`), holding a plus (`some true`) or holding a minus (`some false`). -/
def spr_sign_count {n : ℕ} (b : Fin n → Option Bool) : ℕ :=
  (Finset.univ.filter fun i => (b i).isSome).card

